<script setup>
import {computed,ref} from 'vue';import {alertas,plazo,nombreCurso,diasRestantes,cambiarEstado} from '../store';const avisos=computed(alertas),error=ref(''),filtro=ref('Todas');const visibles=computed(()=>avisos.value.filter(t=>filtro.value==='Todas'||(filtro.value==='Vencidas'?diasRestantes(t)<0:diasRestantes(t)>=0)));async function completar(t){try{await cambiarEstado(t,'Completado')}catch(e){error.value=e.message}}
</script><template><div class="page-heading"><div><div class="eyebrow">SEGUIMIENTO</div><h2>Centro de alertas</h2><p>Revisa los vencimientos y las entregas de los próximos tres días.</p></div></div><div v-if="error" class="alert alert-danger">{{error}}</div><div class="row g-3 mb-4"><div class="col-md-4" v-for="s in [['Todas',avisos.length],['Vencidas',avisos.filter(t=>diasRestantes(t)<0).length],['Próximas',avisos.filter(t=>diasRestantes(t)>=0).length]]" :key="s[0]"><button class="card metric text-start w-100" :class="{'border-primary':filtro===s[0]}" @click="filtro=s[0]"><span>{{s[0]}}</span><strong>{{s[1]}}</strong></button></div></div><div class="card p-4"><h5>Alertas pendientes</h5><p v-if="!visibles.length" class="empty-state">No hay alertas en esta categoría.</p><div v-for="t in visibles" :key="t.id" class="alert-row"><i :class="['bi',diasRestantes(t)<0?'bi-exclamation-triangle text-danger':'bi-clock text-warning']"></i><div class="flex-grow-1"><strong>{{t.nombre}}</strong><div class="small text-secondary">{{nombreCurso(t.curso)}} · {{t.fecha}}</div></div><span class="small fw-semibold">{{plazo(t)}}</span><RouterLink :to="'/actividades?editar='+t.id" class="btn btn-sm btn-outline-primary">Revisar</RouterLink><button class="btn btn-sm btn-outline-success" @click="completar(t)">Completar</button></div></div></template>